export function getCategory(slug: string) {
  return categories.find((category) => category.slug === slug);
}

export function getKeywordPage(categorySlug: string, keywordSlug: string) {
  const category = getCategory(categorySlug);
  return category?.keywords.find((keyword) => keyword.slug === keywordSlug);
}
